/**
 * Resolve the hosted (managed) deployment a `--prod` command addresses: its
 * slug, and the portal playground URL for it.
 */
import { basename, resolve } from "node:path";
import { cursorWebsiteUrl } from "./cursor/credentials.js";
import { validateDeploymentSlug } from "./deploy-client.js";
import { slugFromDirectoryName } from "./slug.js";
/**
 * The portal playground for a hosted deployment, optionally deep-linked to
 * one session. The portal resolves the team from the signed-in browser
 * session, so this needs no API call.
 */
export function prodPlaygroundUrl(slug, sessionId) {
    const url = new URL(`/dashboard/deployed-agents/${encodeURIComponent(slug)}/playground`, cursorWebsiteUrl());
    const session = trimNonEmpty(sessionId);
    if (session !== undefined) {
        url.searchParams.set("sessionId", session);
    }
    return url.toString();
}
/** The hosted deployment's page in the Cursor dashboard. */
export function prodDeploymentUrl(slug) {
    return new URL(`/dashboard/deployed-agents/${encodeURIComponent(slug)}`, cursorWebsiteUrl()).toString();
}
export function trimNonEmpty(value) {
    if (value === undefined) {
        return undefined;
    }
    const trimmed = value.trim();
    return trimmed === "" ? undefined : trimmed;
}
/** Resolve the deployment slug the same way `deploy` does for a single dir. */
export function resolveProdSlug(options) {
    if (options.slug !== undefined && options.slug !== "") {
        const slugError = validateDeploymentSlug(options.slug);
        if (slugError !== undefined) {
            throw new Error(slugError);
        }
        return options.slug;
    }
    const dir = resolve(options.cwd ?? process.cwd(), options.dir);
    const derived = slugFromDirectoryName(basename(dir));
    if (derived === undefined) {
        throw new Error(`Could not derive a deployment slug from the directory name ${JSON.stringify(basename(dir))}; pass --slug.`);
    }
    return derived;
}
